{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RSO no-fault eviction relocation assistance","requirement":"For a no-fault eviction of an RSO-covered unit, the landlord must file a Declaration of Intent to Evict with LAHD before serving notice, file a copy of the notice within 3 days, and pay relocation assistance within 15 days of service.","key_value":"$10,550–$27,400 per unit (July 1, 2026–June 30, 2027)","coverage_conditions":"No-fault evictions from units covered by the Rent Stabilization Ordinance (RSO); all RSO units are Protected Units.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Reduced relocation payments for mom-and-pop owners of four or fewer units"},"exemptions":"Resident manager replaced by another resident manager; eviction required by a natural disaster not caused by landlord negligence; landlord may offset the tenant's accumulated rent against relocation assistance except where a government order requires termination.","penalty":"Failure to file the Landlord Declaration makes the eviction a violation of the RSO; the tenant may raise non-payment of relocation assistance as an affirmative defense.","effective_date":"2026-07-01","citation":"L.A. Mun. Code § 151.09","quoted_span":"All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO).","interaction":"Relocation amounts must be enhanced for lower income tenants under the State Housing Crisis Act.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"JCO no-fault eviction relocation assistance","requirement":"For a no-fault eviction of a JCO-covered unit, the landlord must file a Declaration of Intent to Evict with LAHD before serving notice and pay relocation assistance within 15 days; a natural-person owner of a single-family dwelling owes one month's rent.","key_value":"$10,550–$27,400 per unit (July 1, 2026–June 30, 2027); one month's rent for natural-person-owned single-family dwellings","coverage_conditions":"No-fault evictions from units covered by the Just Cause Ordinance (JCO), including single-family dwellings owned by natural persons.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":4,"owner_dependent":true,"other":"Natural-person owner of a single-family dwelling with no more than four dwelling units and one other single-family home"},"exemptions":"Resident manager replaced by another resident manager; eviction required by a natural disaster not caused by landlord negligence; landlord may offset the tenant's accumulated rent against relocation assistance except where a government order requires termination.","penalty":"Failure to file the Landlord Declaration makes the eviction a violation of the JCO; the tenant may raise non-payment of relocation assistance as an affirmative defense.","effective_date":"2026-07-01","citation":"L.A. Mun. Code § 165.03","quoted_span":"All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO).","interaction":"Relocation amounts must be enhanced for lower income tenants under the State Housing Crisis Act.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D043-01","doc_id":"D043","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Resident Protections Ordinance relocation for demolition for new construction","requirement":"An owner demolishing a Protected Unit for new construction must comply with the RPO relocation rules, pay the highest of State or City relocation amounts, and provide relocation services and up to 6 months' notice to move out.","key_value":"$250,000 per displaced unit minimum penalty","coverage_conditions":"Protected Units demolished for new construction: units rent-restricted or rent-controlled (including all RSO units) or rented by lower income households within the past five years.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Protected Units demolished for the purpose of new construction"},"exemptions":"The regular RSO or JCO relocation rules apply if the units to be demolished are not Protected Units or are not occupied by a lower income tenant.","penalty":"Financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","effective_date":"2025-02-11","citation":"L.A. Ordinance Nos. 188481, 188482","quoted_span":"Failure to comply with the RPO may result in financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.","interaction":"City law requires the higher of State Housing Crisis Act or City relocation amounts.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
